def petals(n, cx, cy, rr, pr, col):
    return "".join(e(cx + rr * math.cos(i * 2 * math.pi / n), cy + rr * math.sin(i * 2 * math.pi / n), pr, pr * .62, col, i * 360 / n) for i in range(n))

